// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Geleneksel el sanatları, somut olmayan kültürel miras ve unutulmaya yüz tutmuş meslekler (telkâri, sedefkârlık, bakırcılık, keçecilik, yazmacılık, oltu ve lületaşı) (kolay).
const ozCulture16Kolay = <(String, String, List<String>, String)>[
  ('Mardin\'in Midyat ilçesi ile Ankara\'nın Beypazarı ilçesinde ustalaşılan, ince gümüş veya altın tellerin bükülüp küçük motifler hâlinde birbirine kaynaklanmasıyla üretilen kuyumculuk sanatı nasıl adlandırılır?', 'Telkâri', ['Savatlama', 'Tombaklama', 'Mıhlama'], 'Telkâri, haddeden çekilmiş çok ince gümüş veya altın tellerin kıvrılıp lehimlenmesiyle dantel görünümü verilen geleneksel zanaattır.'),
  ('Eskişehir yöresinde yerin metrelerce altındaki nemli kil katmanları arasından yumrular hâlinde çıkarılan, gözenekli yapısı sayesinde nikotin ve nemi emdiği için pipo üretiminde dünyaca ün kazanan mineral hangisidir?', 'Lületaşı', ['Kehribar', 'Çakmaktaşı', 'Alabaster'], 'Magnezyum silikat yapısındaki lületaşı (sepiyolit), hafifliği, kolay işlenebilirliği ve sıvı emme kapasitesiyle pipo yapımının baş malzemesidir.'),
  ('Geleneksel kalaycı dükkânlarında yere açılan çukur ocakta kömür ateşini harlamak için ayakla veya elle basılarak hava üfleyen deriden yapılmış katlanabilir körük aracının işlevi nedir?', 'Ocağa basınçlı oksijen sağlayarak kalay ve bakırı çalışma sıcaklığına ulaştırmak', ['Nişadır dumanını emerek ustanın zehirlenmesini doğrudan engellemek', 'Erimiş kalayın hızla soğuyup mat bir tabaka oluşturmasını sağlamak', 'Bakır kabın üzerindeki eski kalay kalıntılarını vakumlayarak çekmek'], 'Kalaycı körüğü, kor hâlindeki odun kömürüne sürekli hava üfleyerek bakırın tavlanması ve kalayın erimesi için gereken ısıyı üretir.'),
  ('Sıcak demirin dövülüp şekillendirildikten sonra aniden soğuk suya, yağa veya havaya daldırılarak kristal yapısının sertleştirilmesi işlemine geleneksel demircilikte ne denir?', 'Su verme', ['Tavlama', 'Perdahlama', 'Haddeleme'], 'Kesici aletlerin ve çelik uçların aşınmaya dirençli hâle gelmesi için kızgın hâldeyken sıvıya batırılıp soğutulmasına su verme denir.'),
  ('Gaziantep ve Kahramanmaraş bakır çarşılarında bitmiş bir bakır sahanın dış yüzeyine ucu keskin çelik kalemler ve küçük çekiçle vurularak bitkisel veya geometrik desen işlenmesi tekniği nedir?', 'Kalem işi bezeme', ['Tel çekme', 'Sıvama', 'Kum döküm'], 'Bakır kapların dış yüzeyine zıpkın veya çelik kalemlerle oyma ve kabartma motifler işlenmesine bakırcılıkta kalem işi (nakışçılık) denir.'),
  ('Trabzon\'da telkâri ve kazaziye dışında gelişen, gümüş veya altın tellerin örgü şişlerine benzer tığlarla sepet örgüsü biçiminde örülmesiyle yapılan bilezik zanaatı hangisidir?', 'Trabzon hasır bilezik örücülüğü', ['Sivas gümüş ağızlık kakmacılığı', 'Diyarbakır kişniş kolye dökümcülüğü', 'Edirne mis sabunu kalıpçılığı'], 'Trabzon hasırı, 31 veya 32 mikron inceliğindeki altın ya da gümüş tellerin el tezgâhında ilmek ilmek sıkıştırılarak örülmesiyle üretilir.'),
  ('Muğla\'nın Yatağan beldesinde Osmanlı döneminden beri demir ustalarınca dövülen ve kabzası kulaklı, namlusu içbükey hafif kavisli olan ünlü kesici silah hangisidir?', 'Yatağan پالا ve kılıcı', ['Çift ağızlı kama hançeri', 'Geniş namlulu teber baltası', 'Düz sırtlı Sürmene saldırması'], 'Yatağan kılıcı/bıçağı, ağırlık merkezini öne taşıyan özel içe kavisli namlusu ve kemik ya da boynuzdan kulaklı kabzasıyla tanınır.'),
  ('Trabzon Sürmene\'de el dövmesi bıçak üreten ustaların kesici çeliğe ideal esneklik ve sertlik kazandırmak için çeliği bitmiş hâle getirdikten sonra bileyip kılağısını aldıkları doğal taş nedir?', 'Su ile ıslatılan ince gözenekli bileyi taşı', ['Kuru olarak sürtülen iri taneli pomza taşı', 'Ateşte kızdırılmış kırmızı tuğla kırığı', 'Tuzlu suda bekletilmiş kireçtaşı bloğu'], 'Sürmene bıçakçılığında su verilmiş namlu, çeliğin suyunu kaçırmamak için su soğutmalı doğal bileyi ve yağ taşlarında keskinleştirilir.'),
  ('Anadolu\'da kapı tokmakları, şamdanlar ve havanlar üretilirken bakıra çinko karıştırılmasıyla elde edilen sarı renkli ve altın görünümüne yakın metal alaşımı hangisidir?', 'Pirinç', ['Tunç', 'Lehim', 'Pik demir'], 'Bakır ve çinko alaşımı olan pirinç (sarı), döküme elverişliliği ve parlak altın sarısı rengi nedeniyle geleneksel kapı tokmakları ve havanlarda yaygın kullanılır.'),
  ('Bakıra kalay karıştırılmasıyla üretilen, pirince göre daha tok ses veren ve darbelere dayanıklı olduğu için çan, dibek ve top dökümünde tercih edilen alaşım nedir?', 'Tunç', ['Alüminyum', 'Galvaniz', 'Nikelaj'], 'Tunç (bronz), bakırın kalayla alaşımlanmasıyla elde edilir; aşınma direnci ve akustik tınısı yüksek olduğu için çan ve havan dökümünde idealdir.'),
  ('Nalbantlıkta hayvanın tırnağına çakılan özel yassı başlı çivilere geleneksel meslek dilinde ne ad verilir?', 'Mıh', ['Perçin', 'Kama', 'Zıvana'], 'At ve öküz nallarını hayvanın canlı dokusuna zarar vermeden boynuzsu tırnak duvarına tutturmaya yarayan özel çivilere mıh denir.'),
  ('Geleneksel demirci dükkânında üst yüzeyi düz çelikleştirilmiş, bir ucu konik boynuz biçiminde uzanan ve kızgın demirin üzerinde dövüldüğü ağır çelik kütle nedir?', 'Örs', ['Mengene', 'Balyoz', 'Kıskaç'], 'Örs, sıcak demirin çekiç ve balyozla şekillendirildiği temel altlıktır; konik boynuz kısmı demire halka ve kavis formu vermeye yarar.'),
  ('Nevşehir, Ürgüp ve Avanos çevresindeki geleneksel konut ve kemer inşaatlarında kullanılan, kolay yontulup havayla sertleşen açık renkli tüf taşını işleyen ustalara ne denir?', 'Taş yontucu', ['Lületaşı oymacısı', 'Kündekâr ustası', 'Horasan harççısı'], 'Kapadokya yöresinde volkanik tüf kayaları tarak, murç ve şakülle yontarak kemerli taş odalar inşa eden ustalara taş yonucu denir.'),
  ('Bakır bir tencerenin kalay tabakası aşınıp alttaki kırmızı bakır göründüğünde yemek pişirilmeye devam edilmesi hangi sağlık riskini doğurur?', 'Asitli gıdaların bakırla tepkimeye girerek bakır oksit/zehirli bileşikler (çalma) oluşturması', ['Yemeğin içindeki demir mineralinin mıknatıslanarak besin değerini tamamen yitirmesi', 'Bakırın kaynama noktasını düşürerek yemeklerin çiğ kalmasına yol açması', 'Tencere tabanının aniden delinerek ocak ateşini söndürmesi'], 'Kalaysız bakır kapta bekleyen veya pişen yemekler bakır tuzları (halk dilinde bakır çalması) oluşturarak akut gıda zehirlenmesine neden olur.'),
  ('Taş işçiliğinde büyük bir kaya kütlesinden parça koparmak veya kaba yontu yapmak için çekiçle arkasına vurulan sivri uçlu çelik kalem hangisidir?', 'Murç', ['Törpü', 'Mala', 'Şakül'], 'Murç, taş ustalarının kaya bloklarını delmek, yarmak ve kaba fazlalıkları koparmak amacıyla balyoz veya çekiçle birlikte kullandıkları sivri çelik keskidir.'),
  ('Geleneksel bakır dövme atölyelerinde çırakların usta ile ritmik uyum içinde karşılıklı geçerek kızgın bakır külçeyi büyük çekiçlerle yassıltma işleminde kullandıkları ağır çekiç nedir?', 'Varyoz', ['Tokmak', 'Keser', 'Perdah kalemi'], 'Bakır külçenin (külçe/tabla) levha hâline getirilmesi aşamasında usta yönlendirici küçük çekiç vururken kalfalar ağır varyozlarla (balyoz) ritmik darbeler indirir.'),
  ('Afyonkarahisar ve Marmara Adası gibi merkezlerde gelişen geleneksel mermer işçiliğinde hamamlara yapılan, sıcak ve soğuk suyun birleştiği oymalı mermer tekneye ne ad verilir?', 'Kurna', ['Şadırvan', 'Yalak', 'Musalla'], 'Türk hamam kültüründe duvar dibine yerleştirilen, dışı mukarnas veya çiçek kabartmalarıyla süslü mermer su çanaklarına kurna denir.'),
  ('Burdur ve Gaziantep gibi illerde bakırcılıktan ayrı bir kol olarak keçi ve koyun sürülerinin boynuna takılan, sesi uzak mesafeden duyulan metal çıngırakları üreten usta kimdir?', 'Çancı', ['Nalbant', 'Kalcı', 'Hakkâk'], 'Sürüdeki hayvanların kaybolmaması ve sürü düzeninin korunması için sac dövme veya tunç döküm yöntemiyle akortlu çan üreten ustaya çancı/kelekçi denir.'),
  ('Taş ustalarının örme bir kemerin veya duvarın tam düşey hizada yükselip yükselmediğini kontrol etmek için ucuna kurşun/pirinç ağırlık bağlanmış iple yaptıkları ölçüm aracı hangisidir?', 'Şakül', ['Gönye', 'Pergel', 'Mastar'], 'Şakül, yer çekimi doğrultusundan yararlanarak duvar ve sütunların şakulünde (tam dikey) örülüp örülmediğini denetleyen konik ağırlıklı iptir.'),
  ('Taş kemerlerin tam tepe noktasına son olarak çakılan ve iki yandan gelen basıncı dengeleyerek kemerin ayakta durmasını sağlayan kama biçimli taşa ne ad verilir?', 'Kilit taşı', ['Üzengi taşı', 'Söve taşı', 'Harpuşta taşı'], 'Kemerin tepe noktasındaki kama kesitli kilit taşı, iki kanattaki kemer taşlarını birbirine sıkıştırarak yapının yükünü yan ayaklara aktarır.'),
  ('Demirci ustasının kızgın demiri ateşten alıp örs üzerinde çevirerek döverken elinin yanmaması için kullandığı uzun kollu metal tutucu alet nedir?', 'Kıskaç', ['Suntraç', 'Keski', 'Burgu'], 'Demirci kıskacı, farklı kalınlık ve profillerdeki akkor hâlindeki metalleri sıkıca kavrayıp örs üzerinde güvenle yönlendirmeye yarar.'),
  ('Geleneksel bakır mutfak eşyaları arasında ortası kubbeli kapaklı, kenarları yayvan kulplu olarak dövülen ve Anadolu\'da yemek servisinde kullanılan sığ kaba ne ad verilir?', 'Sahan', ['Güğüm', 'Lenger', 'Sitil'], 'Bakır sahan, içinde yumurta veya et yemekleri pişirilip sıcak kalması için kubbeli kapağıyla sofraya getirilen iki kulplu sığ kaptır.'),
  ('Bakırcılıkta su taşımak veya ocak kenarında su ısıtmak amacıyla üretilen, gövdesi şişkin, boynu dar, ağzı kapaklı ve tek kulplu büyük bakır kap hangisidir?', 'Güğüm', ['Sini', 'Kevgir', 'Teشت'], 'Güğüm, geleneksel Anadolu evlerinde çeşmeden su taşımak ve soba/ocak üstünde sıcak su bulundurmak için dövülen kulplu bakır kaptır.'),
  ('Üzerinde yer sofrası kurulan, çapı geniş, kenarları hafif kalkık ve genellikle kalem işiyle süslü yuvarlak bakır veya pirinç tepsiye geleneksel kültürde ne ad verilir?', 'Sini', ['Kurna', 'Pota', 'Kefe'], 'Kasnak veya katlanır ahşap ayak (iskemle) üzerine konularak etrafında yemek yenilen büyük yuvarlak metal tepsiye sini denir.'),
  ('Kuyumculukta ve maden sanatında altın, gümüş veya bakırı yüksek sıcaklıkta eritmek amacıyla kullanılan, ateşe dayanıklı grafit veya şamot kilinden yapılmış kap hangisidir?', 'Pota', ['Hadde', 'Örs', 'Lenger'], 'Metal külçelerin ve hurdaların yüksek dereceli ocaklarda sıvı hâle gelene kadar eritildiği ısıya dirençli kaba pota adı verilir.'),
  ('Bakırcılar çarşısında üretilen geleneksel el ibriklerinde suyun ince ve kontrollü akmasını sağlayan kıvrık boru kısmına ne ad verilir?', 'Emzik', ['Kordon', 'Kulp', 'Kaide'], 'Abdest ve el yıkama ibriklerinde gövdeden yukarı doğru zarifçe kıvrılarak uzanan su akıtma borusuna emzik veya lüle denir.'),
  ('Kalaycılık mesleğinin Anadolu\'da gezici ustalar tarafından köy köy dolaşılarak icra edilmesinin tarihsel ve pratik nedeni aşağıdakilerden hangisidir?', 'Köylülerin ağır bakır kazanlarını şehre taşıması zor olduğundan ustanın körük ve takımıyla köye gitmesi', ['Kalay madeninin yalnızca yayla derelerinin kenarında açık havada eritilebilmesi', 'Şehir merkezlerinde kömür ocağı yakılmasının lonca kurallarınca tamamen yasaklanması', 'Bakır kapların yılda sadece hasat günü güneş tutulurken kalaylanabilmesi'], 'Gezici kalaycılar (çerçi/seyyar ustalar) körüğünü, nişadırını ve kalay külçesini eşeğine yükleyip köylerde meydan ocağı kurarak evlerin bakır kaplarını yenilerdi.'),
  ('Gümüşhane, Tokat ve Kastamonu gibi merkezlerde de örnekleri görülen bakır semaver yapımcılığında semaverin ortasından geçen ve kömür ateşinin suyu çabuk kaynatmasını sağlayan dikey boruya ne denir?', 'Ateşlik borusu', ['Demlik emziği', 'Kül çekmecesi', 'Kordon halkası'], 'Semaverin su haznesinin tam ortasından geçen dikey ateşlik borusu, kor kömürün ısısını suyun merkezinden vererek yüksek verim sağlar.'),
  ('Erzurum Oltu taşı tespihlerin ucuna takılan uzun konik parçaya geleneksel tespihçilik terminolojisinde ne ad verilir?', 'İmame', ['Habbe', 'Nişane', 'Frenk'], 'Tespih dizisinin iki ucunun birleştiği, özenle torna edilip bazen gümüş telkâri veya kazaz püskülle süslenen uzun parçaya imame denir.'),
  ('Kütahya, Afyon ve Bilecik hattındaki geleneksel taş ve mermer atölyelerinde buğday dövmek için tek parça sert bazalt veya mermer bloğun oyulmasıyla üretilen büyük taş çukura ne ad verilir?', 'Dibek', ['Söve', 'Kurna', 'Çörten'], 'Dibek, tahıl, kahve veya keşkeklik buğdayın tahta ya da demir tokmaklarla dövülerek kabuğundan ayrıldığı derin taş oyuktur.'),
  ('Selçuklu ve Osmanlı ahşap sanatında minber ve kapı kanatlarında hiçbir çivi veya tutkal kullanılmadan, küçük geometrik ahşap parçaların zıvana ve oluklarla birbirine geçirilmesi tekniği hangisidir?', 'Hakiki kündekâri', ['Edirnekâri lake boyama', 'Alçı revzen vitray', 'Kalemişi sıva nakşı'], 'Kündekâride suyuna göre kesilmiş küçük sekizgen, yıldız ve baklava biçimli ahşap parçalar kinişli çıtalarla kenetlenir; nem değişiminde çatlama yapmaz.'),
  ('Gaziantep ve Şam geleneğinden İstanbul saray atölyelerine uzanan sedefkârlık sanatında ceviz ağacına açılan yuvalara kakılan sedefin doğal kaynağı nedir?', 'Deniz ve tatlı su yumuşakçalarının iç kabuk tabakası', ['Volkanik mağaralardan çıkarılan parlak kuvars kristalleri', 'Fırınlanmış beyaz porselen çamuru ve cam tozu kırıkları', 'İpek böceği kozalarının kaynatılmasıyla dondurulan reçine'], 'Sedef, istiridye ve midye gibi kabuklu deniz canlılarının iç yüzeyindeki yanardöner kalsiyum karbonat tabakasının kesilip inceltilmesiyle elde edilir.'),
  ('Zonguldak\'ın Devrek ilçesiyle özdeşleşen geleneksel baston yapımcılığında esnekliği, darbe dayanımı ve kolay eğilebilirliği nedeniyle gövde için en makbul sayılan ağaç türü hangisidir?', 'Kızılcık ağacı', ['Kavak ağacı', 'Söğüt ağacı', 'Çam ağacı'], 'Devrek bastonlarının gövdesi lif yapısı çok sıkı ve kırılmaya dirençli olan kızılcık dalından, sap kısmı ise genellikle ceviz ağacından üretilir.'),
  ('Konya, Sakarya Taraklı ve Antalya Akseki gibi merkezlerde yaşatılan geleneksel tahta kaşıkçılıkta suya girdiğinde tüylenmemesi ve bakteri barındırmaması nedeniyle tercih edilen en değerli ağaç hangisidir?', 'Şimşir ağacı', ['Göknar ağacı', 'Ihlamur ağacı', 'Kestane ağacı'], 'Çok yavaş büyüyen ve kemik gibi sıkı dokulu olan şimşir ağacı, sıcak yemek ve suda liflenmediği için tahta kaşık yapımının en ideal malzemesidir.'),
  ('Nevşehir\'in Avanos ilçesinde Hititlerden bu yana süregelen çömlekçilik geleneğinde kullanılan kırmızımsı yağlı kilin doğal kaynağı neresidir?', 'Kızılırmak\'ın taşıyıp biriktirdiği alüvyonlu yataklar', ['Erciyes Dağı\'nın zirvesindeki buzulların altındaki bazalt kumları', 'Tuz Gölü kıyı şeridinden çıkarılan beyaz karbonatlı çamurlar', 'Toros Dağları\'ndaki mağaralardan toplanan yarasa gübresi toprağı'], 'Avanos çömleklerine kendine has kızıl rengini ve plastik şekillenme yeteneğini Kızılırmak nehrinin eski yataklarındaki demir oksitçe zengin alüvyonlu killer verir.'),
  ('Geleneksel Avanos çömlekçi tezgâhında (işlik) ustanın iki eliyle çamura şekil verirken üstteki tablayı elektrik motoru olmadan döndürme mekanizması nasıldır?', 'Alt kısımdaki ağır volan tekerleğin ayakla itilerek döndürülmesi', ['Çırağın tezgâh arkasındaki deri körüğe sürekli hava basması', 'Tavandan sarkan ağırlıklı bir sarkaç ipinin yayla boşalması', 'Atölye dışındaki rüzgâr pervanesinin kayışla mili çevirmesi'], 'Ayak çarkında usta otururken ayaklarıyla alttaki büyük ve ağır tekerleği (alt çark) iter; aynı mil üzerindeki üst tabla sarsıntısız biçimde döner.'),
  ('19. yüzyılda İstanbul Beykoz cam atölyelerinde Mevlevi dervişi Mehmet Dede öncülüğünde geliştirilen, saydam cam gövde içinde sarmal beyaz ve renkli çizgiler barındıran üfleme cam tekniği hangisidir?', 'Çeşmibülbül', ['Nazar boncuğu', 'Ebru teknesi', 'Kalemişi'], 'Bülbül gözü anlamına gelen çeşmibülbül, kalıptaki renkli ve süt beyazı cam çubukların sıcak cam kütlesine alınıp üflenirken bükülmesiyle oluşan helezonik desenli cam sanatıdır.'),
  ('Geleneksel Türk müziğinin baş sazlarından ney yapımcılığında 9 boğumlu gövdenin üretilmesi için Hatay Samandağ (Asi Nehri kıyısı) gibi sulak bölgelerden kesilen malzeme hangisidir?', 'Kargı kamışı', ['Bambu ağacı', 'Şimşir dalı', 'Söğüt sürgünü'], 'Ney, sıcak-ılıman nehir kenarlarında yetişen ve dokuz boğumdan oluşan sarı kargı kamışının kurutulup içinin açılması ve yakılarak delinmesiyle yapılır.'),
  ('Anadolu bağlama (saz) yapımcılığında ses kutusu olan \'tekne\' kısmının oyulmasında rezonansı ve sıcak tınısı nedeniyle ustaların yüzyıllardır en çok rağbet ettiği ağaç hangisidir?', 'Dut ağacı', ['Kavak ağacı', 'Salkım söğüt', 'Okaliptüs'], 'Oyma bağlama teknelerinde lif yapısı, dayanıklılığı ve eşsiz akustik tınısı nedeniyle kurutulmuş dut kütüğü birinci sınıf malzeme kabul edilir.'),
  ('Ahşap oymacılığında ceviz veya ıhlamur levha üzerine çizilen çiçek, rumi ve hatayi motiflerini oymak için tokmakla arkasına vurulan farklı ağız yapılarına sahip çelik keskilere ne ad verilir?', 'İskarpela', ['Suntraç', 'Şakül', 'Hadde'], 'İskarpela; düz, oluklu ve V ağızlı çeşitleriyle ahşap oymacısının ağacı yontup derinlikli kabartmalar oluşturmasını sağlayan temel el aletidir.'),
  ('Ağaç işlerinde marangoz ve oymacıların iskarpela sapının yarılmaması için çelik çekiç yerine sert gürgen veya şimşir ağacından yapılmış yuvarlak başlı hangi vurucu aleti kullanmaları gerekir?', 'Ahşap tokmak', ['Demir varyoz', 'Nalbant çekici', 'Taşçı murcu'], 'Metal çekiç ahşap saplı iskarpelayı parçalar ve sert darbe verir; ahşap tokmak ise darbeyi kontrollü ve esnek ileterek hem aleti korur hem hassas oyma sağlar.'),
  ('Menemen, Kınık ve Avanos çömlekçiliğinde kapların iç yüzeyinin su ve yağ sızdırmaması, ayrıca kolay temizlenmesi amacıyla sürülen ve pişince camlaşan tabakaya ne ad verilir?', 'Sır', ['Perdah', 'Horasan', 'Nişadır'], 'Kuvars, metal oksitler ve eriticilerden oluşan sıvı bulamaç (sır), pişmiş veya yarı kuru kaba sürülüp fırınlandığında pürüzsüz, su geçirmez camsı bir katman oluşturur.'),
  ('Geleneksel ahşap beşik ustalarının bebek beşiklerinin üst kısmında iki başlığı birbirine bağlayan yuvarlak uzun çıtayı (tutamak/ok) kalın ve sağlam yapmalarının pratik işlevi nedir?', 'Beşiği taşımaya, örtü atarak bebeği ışıktan korumaya ve kundak bağını sabitlemeye yaraması', ['Beşiğin altındaki kızakların sallanmasını tamamen kilitlemesi', 'Kış aylarında içine sıcak köz konularak bebeği ısıtması', 'Bebek büyüdükçe uzayan teleskopik bir yay barındırması'], 'Anadolu ahşap beşiklerinde \'beşik oku\' veya \'üst gergi kolu\' hem yapıyı rijit tutar hem beşiği kaldırmaya ve üzerine tülbent/örtü germeye yarar.'),
  ('Geleneksel cam üfleme atölyelerinde ustanın potadaki erimiş camı ucuna alıp nefesle şişirdiği içi boş uzun çelik boruya ne ad verilir?', 'Pipo', ['Hadde', 'Körük', 'Suntraç'], 'Cam üfleme sanatının en temel aleti, yaklaşık 1,2–1,5 metre uzunluğundaki içi delik çelik boru olan üfleme piposudur.'),
  ('Osmanlı saray ve tekke kültüründe misafirlere gül suyu ikram etmek için cam, gümüş veya çiniden üretilen, gövdesi şişkin, boynu ince uzun ve ağzı damlalıklı kaba ne ad verilir?', 'Gülabdan', ['Buhurdan', 'Lenger', 'Kurna'], 'Gülabdan (gül suyu kabı), gül suyunun ele azar azar serpilmesini sağlayan dar ağızlı ve armudi gövdeli zarif ikram eşyasıdır.'),
  ('Cam, gümüş veya tombaklı bakırdan yapılan, içinde öd ağacı ya da günlük reçinesi yakılarak kapak deliklerinden hoş kokulu duman yaymasını sağlayan geleneksel eşya nedir?', 'Buhurdan', ['Gülabdan', 'Sini', 'Sitil'], 'Buhurdan, alt haznesindeki kor kömür üzerine konulan tütsü ve öd ağacının dumanını ajurlu (delikli) kubbe kapağından odaya yayan kaptır.'),
  ('Batı Toroslar ve Teke yöresinde su kabağının kurutulup kesilmesi ve ağzına yürek zarı veya ince deri gerilmesiyle gövdesi oluşturulan yaylı halk çalgısı nedir?', 'Kabak kemane', ['Cümbüş', 'Tambur', 'Çeng'], 'Kabak kemane, doğal su kabağı gövdesi, sığır yürek zarı (veya balık/oğlak derisi) göğsü ve at kılı yayıyla tamamen doğadan süzülmüş bir halk sazıdır.'),
  ('Geleneksel marangozluk ve doğramacılıkta ahşap yüzeydeki pürüzleri ince talaş kaldırarak düzeltmeye yarayan, ortasında eğimli kesici çelik tığ bulunan ahşap gövdeli el aleti nedir?', 'Rende', ['Burgu', 'Mengene', 'Kerpeten'], 'Marangoz rendesi, tabanı pürüzsüz sert ağaçtan (gürgen/şimşir) yapılan ve içindeki ayarlı çelik bıçakla tahtayı pürüzsüzleştiren temel tesviye aletidir.'),
  ('Camilerdeki vaaz kürsüleri, rahleler ve konak pencerelerindeki \'muşabak\' (kafes) işçiliğinde ince ahşap çıtaların testereyle yarıya kadar kertilip dik veya eğik açıyla birbirine geçirilmesi ne sağlar?', 'İçeriden dışarının görülmesine ve havanın girmesine izin verirken dışarıdan içerinin görünmesini engeller', ['Yağmur ve kar suyunu tamamen keserek çift cam yalıtımı oluşturur', 'Güneş ışığını mercek gibi odaklayarak odayı kışın ısıtır', 'Sesi dışarıya hoparlör gibi yükselterek duyurur'], 'Geleneksel ahşap pencere kafesleri (muşabak), mahremiyeti korurken serin esinti ve süzülmüş gün ışığı sağlayan çivisiz geçme çıta örgüleridir.'),
  ('Kastamonu, Bartın ve Sinop (Ayancık/Boyabat) gibi ormanlık Karadeniz kentlerinde ceviz veya ıhlamurdan yapılan, katlandığında tek parça tahta gibi kilitlenen x-biçimli geleneksel kitap altlığı nedir?', 'Rahle', ['Kavukluk', 'Sini altı', 'Kurna'], 'Özellikle tek parça kalın bir tahtanın menteşesiz olarak iç içe geçecek biçimde oyulmasıyla yapılan katlanır \'yekpare geçme rahle\' ahşap ustalığının şaheseridir.'),
  ('Anadolu halk kültüründe camaltı resim ustalarının özellikle Mardin, Tarsus ve Hatay çevresinde evlerin duvarları için en sık resmettikleri yarı kadın yarı yılan efsanevi figür hangisidir?', 'Şahmeran', ['Zümrüdüanka', 'Tepegöz', 'Hüma kuşu'], 'Bilgelik, şifa ve sırrı simgeleyen yılanların şahı Şahmeran, Güneydoğu ve Akdeniz\'de camaltı halk resim sanatının en ikonik temasıdır.'),
  ('Ahşap oymacılığında ve sedefkârlıkta ince ahşap veya sedef plakaların iç kısımlarından dantel gibi kıvrımlı boşluklar kesip çıkarmak için kullanılan yaylı el aleti hangisidir?', 'Kıl testeresi', ['Yarma baltası', 'Oluklu keser', 'Geniş rende'], 'U biçimli metal bir kol arasına gerilen saç teli inceliğindeki dişli çelik telden oluşan kıl testeresi, sedef ve ahşapta en dar kavislerin kesilmesini sağlar.'),
  ('Mardin, Gaziantep ve Kahramanmaraş yörelerinde özellikle kadınların hamamda ve taş avluda giydikleri, gövdesi cevizden oyulup üzeri sedef veya gümüş kakmayla süslenen yüksek tabanlı ahşap ayak giysisi nedir?', 'Nalın', ['Yemeni', 'Çarık', 'Mest'], 'Islak hamam mermerinde ayağı yerden yüksek tutmak için yapılan, üzeri gümüş kaplama veya sedef kakmalı çeyizlik ahşap terliklere nalın (gündelik sade olanına takunya) denir.'),
  ('Geleneksel köy evlerinde ayran çalkalamak için çam veya sedir kütüğünün içi oyularak ya da fıçı gibi dilimlenerek yapılan, üç ayaklı sehpaya iple asılıp ileri geri sallanan silindirik ahşap araca ne denir?', 'Ahşap yayık', ['Taş dibek', 'Bakır lenger', 'Demir örs'], 'Yoğurdun tereyağını ayırmak için yapılan ahşap yayıklar ya dikey sopayla (bişek) dövülür ya da üç ayaklı çatala yatay asılarak ileri geri sallanır.'),
  ('Kastamonu Tosya, Bolu Gerede ve Sakarya Taraklı gibi yerlerde şimşir veya gürgen ağacından çok ince ve sık dişli olarak üretilen, baş bitini ve kepeği temizlemekte de kullanılan geleneksel saç bakım eşyası nedir?', 'Şimşir tarak', ['Sedef rahle', 'Kızılcık baston', 'Kargı ney'], 'Elektriklenme yapmayan, saçı kırmayan ve antibakteriyel dokulu şimşir ağacından ince testerelerle tek tek diş açılarak üretilen şimşir taraklar geleneksel bir zanaat ürünüdür.'),
  ('Osmanlı mimarisinde cami kapıları ve pencere kepenklerinde ahşap aynalıkların içine küçük fildişi ve sedef parçalarının kakılması sırasında zeminde en çok tercih edilen koyu renkli yerli ağaç hangisidir?', 'Ceviz ağacı', ['Kavak ağacı', 'Söğüt ağacı', 'Balsa ağacı'], 'Koyu kahverengi hareli dokusu, sertliği ve kurtlanmaya direnci sayesinde ceviz ağacı, beyaz sedef ve fildişinin parlaklığını en güçlü biçimde öne çıkaran ana gövde ağacıdır.'),
  ('Çömlekçi ustasının dönen çark üzerindeki tamamlanmış yaş çömleği tabladan tabanını yamultmadan ayırmak için başvurduğu pratik yöntem hangisidir?', 'İki ucunda tutamak bulunan ince gergin bir tel veya sağlam ipi çömlek tabanı altından çekerek kesmek', ['Çömleği kulplarından tutup yukarı doğru hızla çekerek koparmak', 'Tablanın altına alttan çekiçle vurarak çömleği havaya sıçratmak', 'Çarkın üzerine bir kova soğuk su dökerek çamuru yüzdürmek'], 'Şekillendirme bitince usta iki eline doladığı ince kesme telini (veya misina/ip) dönmeyen ya da yavaş dönen tablanın tam yüzeyinden geçirerek çömleğin altını düzgünce ayırır.'),
  ('Türk halı dokumacılığında iki çözgü teli arasına düğüm atılırken ipliğin her iki çözgü telinin etrafından tam tur dolandırılıp ortadan çıkarılmasıyla oluşturulan sağlam düğüm tekniğine ne ad verilir?', 'Gördes (Türk) düğümü', ['Sine (İran) tek dolama düğümü', 'Çözgü yüzlü cicim atlaması', 'Atkı sarma sumak ilmeği'], 'Anadolu halılarının karakteristik özelliği olan çift düğüm tekniğine Manisa Gördes\'e atfen Gördes (veya Türk) düğümü denir ve tek dolamalı İran düğümünden daha sıkıdır.'),
  ('Halı dokuma tezgâhında her sıra düğüm atıldıktan ve atkı ipliği geçirildikten sonra ilmekleri aşağı doğru vurup sıkıştırmak için kullanılan ağır dişli el aleti hangisidir?', 'Kirkit', ['Kemanlı hallaç yayı', 'Eğri uçlu dokuma bıçağı', 'Çevirmeli masura çıkrığı'], 'Demir veya sert şimşir dişlerden oluşan kirkit, halı ve kilim tezgâhlarında atkı ve düğüm sıralarını döverek dokumanın sıkı ve düzgün olmasını sağlar.'),
  ('Dokuma tezgâhlarında yukarıdan aşağıya doğru dikey ve gergin biçimde dizilen, halı ya da kumaşın ana iskeletini oluşturan boyuna iplik grubuna ne ad verilir?', 'Çözgü', ['Mekikle enine atılan atkı ipliği', 'Yüzeyde hav oluşturan ilmek yünü', 'Kenar saçaklarını bağlayan pürçek'], 'Tezgâha dokuma başlamadan önce boyuna gerilen temel taşıyıcı ipliklere çözgü, bunların arasından yatay geçirilen ipliklere ise atkı denir.'),
  ('Havlı (tüylü) halılardan farklı olarak düğüm atılmadan yalnızca çözgü ve renkli atkı ipliklerinin alt-üst geçirilmesiyle üretilen düz dokuma yaygı türü hangisidir?', 'Kilim', ['Çift düğümlü yün halı', 'Uzun tüylü tülü dokuma', 'Kabartma havlı kadife'], 'Kilim, havsız düz dokuma grubunun en temel örneğidir; desenler renkli atkı ipliklerinin çözgüleri tamamen gizleyecek biçimde sıkıştırılmasıyla iki yüzü bir olarak oluşur.'),
  ('Kocaeli\'nin Körfez kıyısındaki Hereke beldesinde 19. yüzyılda saray için kurulan dokumahane ile dünyaca ünlenen ve santimetrekaresinde yüzlerce düğüm barındıran en ince halı türü hangisidir?', 'Saf ipek Hereke halısı', ['Kalın yünlü Konya tülü halısı', 'Keçi kılından Siirt battaniyesi', 'Pamuk atkılı Buldan dokuması'], 'Çözgüsü, atkısı ve ilmeği tamamen Bursa ham ipeğinden dokunan Hereke halıları, incecik Gördes düğümleriyle dünya halıcılığının en zarif zirvesi kabul edilir.'),
  ('Çanakkale Ayvacık, Manisa Yuntdağı, Milas ve Bergama gibi Batı Anadolu yörelerinde göçebe Yörük kültürünün izlerini taşıyan halı ve kilimlerdeki \'eli belinde\' motifi neyi simgeler?', 'Analık, doğurganlık, bereket ve uğuru', ['Kabileler arası savaş ilanını ve intikamı', 'Ölüm acısını, ayrılığı ve yas tutmayı', 'Yalnızca akrep ve yılan sokmasından korunmayı'], 'Anadolu dokuma sembolizminde kollarını beline koymuş stilize kadın figürü olan \'eli belinde\', ailenin devamını, doğurganlığı ve bolluğu temsil eder.'),
  ('Geleneksel Anadolu kilim ve halılarında dokuyucunun nazardan ve kötü gözden korunma dileğini yansıtan üçgen, göz veya çengel kenarlı baklava biçimindeki motif grubu hangisidir?', 'Muska ve göz motifleri', ['Koçboynuzu ve hançer motifleri', 'Sandıklı ve küpeli çeyiz motifleri', 'Su yolu ve hayat ağacı motifleri'], 'Üçgen biçimli muska ve stilize edilmiş dördül göz motifleri, nazarı geri çevirdiğine ve evi koruduğuna inanılan en yaygın koruyucu sembollerdir.'),
  ('Anadolu kilimlerinde yiğitlik, erkeklik gücü ve kahramanlığı simgeleyen iki yana kıvrık sarmal motif aşağıdakilerden hangisidir?', 'Koçboynuzu', ['Küpeli çiçeği', 'Saçbağı motifi', 'Bukağı işareti'], 'Eli belinde motifi dişiliği ve analığı temsil ederken, iki yana güçlü biçimde kıvrılan koçboynuzu motifi erilliği, gücü ve sürü bereketini simgeler.'),
  ('Siirt\'te tiftik keçisinden kırkılan beyaz, siyah ve kahverengi tüylerin boyanmadan kirmanla eğrilip dokunması ve ardından çelik taraklarla tüylendirilmesiyle üretilen ünlü ürün hangisidir?', 'Siirt tiftik battaniyesi', ['Uşak madalyonlu halısı', 'Bursa çatması yastık yüzü', 'Denizli horozlu havlusu'], 'Siirt battaniyesi saf tiftik (moher) dokunduktan sonra yüzeyinin demir dişli tarakla kabartılıp havlandırılması sayesinde hafif ama çok yüksek ısı yalıtımlı olur.'),
  ('Hiçbir dokuma tezgâhı, çözgü veya atkı ipliği kullanılmadan; taranmış koyun yününün ılık sabunlu su, nem, ısı ve beden gücüyle dövülüp yuvarlanarak liflerinin kenetlenmesiyle yapılan zanaat nedir?', 'Tepme keçecilik', ['Çarpana dokumacılığı', 'Mekikli bez dokumacılığı', 'Tığ işi dantel örücülüğü'], 'İnsanlığın dokumadan da eski tekstil tekniği olan keçecilik; Afyon, Konya, Tire, Urfa ve Kars\'ta yün liflerindeki pulların sıcak sabunlu su ve baskıyla birbirine geçmesine dayanır.'),
  ('Anadolu yaylalarında çobanların dondurucu soğuktan, yağmurdan ve rüzgârdan korunmak için omuzlarına aldıkları; dikişsiz, kolsuz ve dik omuzlu sert tepme keçe giysi hangisidir?', 'Kepenek', ['Cepken', 'Şalvar', 'Fermene'], 'Çoban kepeneği tek parça kalın dövülmüş yün keçeden yapılır; su geçirmez, dik durur ve acil durumda çobanın içinde uyuyabileceği çadır-yatak görevi görür.'),
  ('Geleneksel el eğirmeciliğinde yün veya keçi kılı tutamını burkarak ipliğe dönüştürmek için ustanın elinde çevirdiği artı (+) biçimli kanatlı ahşap araca ne ad verilir?', 'Kirman', ['Mekik', 'Tef', 'Cendere'], 'Kirman ve iğ, çıkrıktan daha taşınabilir olan ve Yörük kadınlarının yürürken bile yün veya kıl eğirip iplik bükmesini sağlayan kadim el araçlarıdır.'),
  ('Ham hayvan derilerini tuzlama, kireçleme, kıllarından sıyırma ve bitkisel tanenlerle (palamut, mazı, sumak) işleyerek çürümez kullanışlı deri hâline getiren geleneksel zanaatkâra ne denir?', 'Debbağ', ['Saraç', 'Nalbant', 'Hallaç'], 'Ahilik teşkilatının kurucusu Ahi Evran\'ın da mesleği olan debbağlık (tabaklık), ham deriyi terbiye edip sahtiyan, kösele ve meşine dönüştüren temel zanaattır.'),
  ('Gaziantep ve Kilis\'te yaşatılan geleneksel yemenicilikte, üst sayası kırmızı veya siyah keçi derisinden (sahtiyan), alt tabanı manda köselesinden hiçbir çivi ve sentetik yapıştırıcı kullanılmadan dikilen ayakkabı nedir?', 'Yemeni', ['Ahşap nalın', 'Yün çorap', 'Keçe çizme'], 'Yemeninin tabanı manda köselesi, üstü keçi sahtiyanı, iç astarı koyun meşinidir; balmumlu pamuk ipliğiyle tersinden elde dikilip çevrilir ve ayağı hiç terletmez.'),
  ('Yemeni ustalarının ayakkabının alt köselesi ile üst derisini balmumlu keten/pamuk ipliğiyle birleştirirken delik açmak için kullandıkları ucu sivri çelik delici alet hangisidir?', 'Biz', ['Kirkit', 'Suntraç', 'Mühre'], 'Saraçlık, kunduracılık ve yemenicilikte kalın deri ve kösele katmanlarını iğnenin geçebileceği şekilde delmeye yarayan ahşap saplı sivri çelik uca biz denir.'),
  ('Anadolu köylüsünün ve çobanlarının yakın geçmişe kadar giydikleri; tek parça tuzlanmış-yağlanmış sığır veya manda ham derisinin (gön) ayak formuna göre büzülüp sırımla bağlanmasıyla yapılan ayakkabı nedir?', 'Çarık', ['Kaloş', 'Mest', 'Takunya'], 'Çarık, işlenmemiş veya yarı işlenmiş kalın sığır/manda gönünün kenarlarında açılan gözeneklerden deri sırım geçirilip ayağı saracak biçimde büzülmesiyle yapılan esnek kır ayakkabısıdır.'),
  ('At, eşek ve katırların sırtına yük vurulduğunda hayvanın omurgasının ezilip yara olmasını önlemek için saz kamışı, keçe, deri ve ahşap iskeletle üretilen taşıyıcı yastığı yapan usta kimdir?', 'Semerci', ['Nalbant', 'Kalaycı', 'Çıkrıkçı'], 'Semercilik; hayvanın sırt anatomisine göre gürgen/ceviz ağacından kaş iskeleti kurup içine göl sazı (hasır otu) doldurarak keçe ve deriyle kaplama sanatıdır.'),
  ('Yatak, yorgan ve yastıkların içindeki zamanla topaklanıp sertleşmiş yün veya pamuğu kirişli büyük bir yay ve ahşap tokmakla titreştirerek yeniden kabartan geleneksel zanaatkâr kimdir?', 'Hallaç', ['Urgancı', 'Keçeci', 'Kazzaz'], 'Hallaç, koyun bağırsağından yapılma gergin kirişe sahip hallaç yayına \'çekcek\' adlı ahşap tokmakla vurarak çıkardığı titreşimle pamuk ve yünü bulut gibi kabartır.'),
  ('Geleneksel el yorgancılığında saten veya basma yorgan yüzünün içindeki kabartılmış pamuk/yünün kayıp toplanmaması ve yüzeyde selvi, yıldız, yelpaze gibi kabartma desenler oluşması nasıl sağlanır?', 'Yüksük yardımıyla binlerce küçük ve eşit aralıklı teğel dikişinin (sırık/nakış) el iğnesiyle işlenmesiyle', ['Pamuğun kumaş arasına sıcak çiriş tutkalı dökülerek taş gibi yapıştırılmasıyla', 'Yorganın dıştan ince bakır tellerle kafes biçiminde sarılmasıyla', 'Desen çizgilerinin sıcak ütüyle yakılarak kumaşa bastırılmasıyla'], 'Yorgancı ustası parmağına taktığı yüksükle kalın yorganı alttan üste \'sırıyarak\' hem dolgu malzemesini sabitler hem de çeyizlik kabartma motifler meydana getirir.'),
  ('Kırklareli, Edirne, Karamürsel ve Rize gibi yörelerde fındık sürgünü, söğüt dalı, kestane şeridi veya kamış kullanılarak çivi çakılmadan örülen taşıma kapları hangi zanaatın ürünüdür?', 'Sepet örücülüğü', ['Kündekâri doğramacılığı', 'Hatemkâri kakmacılığı', 'Edirnekâri boyamacılığı'], 'Sepetçilik; fındık, kestane veya söğüt dallarının yaşken ya da ıslatılarak esnetilip kaburga çubukları etrafında örülmesiyle küfe, sele ve sepet üretme sanatıdır.'),
  ('Doğu Karadeniz\'de çay, fındık, ot veya odun taşımak amacıyla fındık dallarından konik biçimde örülen ve iki kalın kolan ipiyle omuzlardan sırta yüklenen taşıma sepetine ne ad verilir?', 'Sırt küfesi', ['Eyer heybesi', 'Buğday kalburu', 'Peynir küleği'], 'Dik yamaçlı Karadeniz arazisinde tekerlekli araç işlemediği için fındık sürgünlerinden örülen konik sırt sepetleri (küfe/şelek) bölge insanının en temel taşıma aracı olmuştur.'),
  ('Sulak alanların ve göllerin çevresinde (Afyon Eber Gölü, Kayseri Sultan Sazlığı, Hatay Amik) biçilen \'kofa / berdi\' sazlarının kurutulup yer tezgâhında dokunmasıyla üretilen sergi nedir?', 'Hasır', ['Savvan', 'Cicim', 'Tülü'], 'Hasırcılık, göl kamışı ve sazlarının nem yalıtımı sağlayan doğal dokusundan yararlanılarak cami ve ev zeminleri için sergi, zembil ve sepet örülmesi zanaatıdır.'),
  ('Sepet ve hasır ustalarının kurumuş söğüt dallarını veya saz saplarını örmeye başlamadan önce bir süre suda bekletip nemlendirmelerinin amacı nedir?', 'Bitkisel liflere esneklik kazandırarak bükme sırasında kırılıp çatlamalarını önlemek', ['Dalların içindeki reçineyi dondurarak çubukları cam gibi kırılgan yapmak', 'Suyun ağırlığıyla sepetin tabanını yere çivilemek', 'Söğüt dallarının yeniden kök salıp yaprak açmasını sağlamak'], 'Kuru dal ve sazlar büküldüğünde çabucak kırılır; su emdirilerek yumuşatılan lifler ise dar açılarla çatlamadan kıvrılır ve kuruyunca aldığı formu korur.'),
  ('Denizli\'nin Buldan ilçesinde yüzlerce yıldır mekik tezgâhlarında pamuk ve ipek ipliklerle dokunan; peştamal, başörtüsü (hoşkuran) ve gömleklik bezleriyle tanınan geleneksel zanaat merkezi hangi dokuma koluna girer?', 'El tezgâhı çulhalık / bez dokumacılığı', ['Sıcak demirci körükçülüğü', 'Kayıp mum tunç dökümcülüğü', 'Alçı şebeke revzenciliği'], 'Buldan dokumacılığı (tarihsel adıyla çulhalık), kıvrak bükümlü pamuk ve doğal ipekle kamçılı/mekikli ahşap tezgâhlarda nefes alan ince kumaşlar üretme geleneğidir.'),
  ('Ahşap dokuma tezgâhında içine atkı ipliği sarılı masuranın yerleştirildiği, iki ucu sivri ve kaygan şimşir/kızılcık ağacından yapılmış kayık biçimli araca ne ad verilir?', 'Mekik', ['Kirman', 'Biz', 'Eğdi'], 'Mekik, açılan çözgü ağızlığı içinden sağdan sola ve soldan sağa kaydırılarak atkı ipliğini hızlıca bırakan aerodinamik ahşap elemandır.'),
  ('Anadolu\'da göçebe ve köylü ailelerin içine un, tahıl veya çeyiz eşyası koyup deve ya da at sırtında iki yana dengeli astıkları, ön yüzü kilim/cicim/halı dokumalı çift gözlü çantaya ne ad verilir?', 'Heybe', ['Kepenek', 'Peştamal', 'Parazvane'], 'Heybe, ortasında boyun/eyer geçiş yarığı bulunan ve iki yanında cep gözleri yer alan, Yörük dokuma sanatının en zengin motiflerini taşıyan ikiz taşıma torbasıdır.'),
  ('Ayakkabıcılıkta ve mesçilikte namaz abdesti alırken üzerine meshedilebilmesi için ince, yumuşak koyun veya keçi derisinden fermuarlı ya da bağcıksız çorap gibi dikilen iç ayakkabı hangisidir?', 'Mest', ['Çarık', 'Nalın', 'Takunya'], 'Mest, kış aylarında ayağı sıcak tutan ve dış ayakkabı (eskiden lastik veya kaloş/pabuç) içine giyilen ince yumuşak deriden dikilmiş geleneksel ayakkabıdır.'),
  ('Yün kırkımından sonra kirli yapağının tokmakla yıkanıp kurutulmasının ardından liflerin paralel hâle getirilmesi ve pıtraklardan temizlenmesi için iki demir dişli tahta arasında çekilmesine ne denir?', 'Yün tarama', ['Küp boyama', 'Kırkım perdahı', 'Mekik atma'], 'Eğirme veya keçeleme öncesinde karışık yün topakları \'yün tarağı\' adı verilen çivili/dişli düzenekten geçirilerek lifleri açılır ve homojen tülbent hâline getirilir.'),
  ('Manisa Kula, Konya Lâdik, Kırşehir ve Gördes gibi merkezlerde tek yöne bakan kemerli niş kompozisyonuyla dokunan ve ibadet amacıyla kullanılan küçük boy halılara ne ad verilir?', 'Seccade', ['Yolluk halı', 'Sedir yastığı', 'Deve kolanı'], 'Üzerinde kıble yönünü gösteren mihrap kemeri, kandil, ibrik veya hayat ağacı motifleri yer alan tek kişilik ibadet halılarına seccade denir.'),
  ('Seccade halılarının mihrap nişi içine veya kenar bordürüne \'el yıkama ibriği\' motifi dokunması hangi sembolik anlamı taşır?', 'Beden ve ruh temizliğini, abdesti ve arınmayı', ['Yağmursuz geçen kurak mevsimlere isyanı', 'Misafire kahve ve şerbet ikram edilmeyeceğini', 'Evdeki bakır kapların kalaylanma vaktini'], 'Namazlık halı ve kilimlerdeki ibrik motifi maddi ve manevi arınmayı, abdest temizliğini simgeleyen en zarif ibadet sembollerinden biridir.'),
  ('Denizli, Bursa ve Hatay\'da gelişen geleneksel Türk hamam kültürü dokumalarında peştamaldan farklı olarak her iki yüzünde suyu hızla çeken küçük iplik halkaları (hav ilmekleri) bulunan dokuma hangisidir?', 'Havlu', ['Dastar', 'Şayak', 'Kutnu'], 'Dünyaya Bursa ve Osmanlı hamam kültüründen yayılan havlu, gergin zemin çözgüsünün yanında gevşek bırakılan hav çözgüsünün tefe vuruşuyla yüzeyde ilmek yapmasıyla üretilir.'),
  ('Aksaray Sultanhanı ve Konya gibi tarihî halı merkezlerinde asırlık el halılarının sökülen saçaklarını veya güve yeniği deliklerini aslına uygun kök boyalı iplikle görünmez şekilde onaran ustaya ne denir?', 'Halı tamircisi / örücü', ['Sadekâr ustası', 'Lületaşı oymacısı', 'Nalbant kalfası'], 'Özellikle Sultanhanı ve Kapalıçarşı\'da gelişen geleneksel halı onarımcılığı; halının özgün çözgü sayısını, düğüm tipini ve boyasını birebir taklit ederek eksik kısmı yeniden dokuma sanatıdır.'),
  ('Edirne Kırkpınar yağlı güreşlerinde pehlivanların giydikleri ve özel ustalarca manda veya dana derisinden kalın balmumlu sicimlerle elde dikilen dar paçalı deri giysiye ne ad verilir?', 'Kıspet', ['Kepenek', 'Fermene', 'Yemeni'], 'Kıspet dikiciliği geleneksel deri zanaatının özel bir dalıdır; bel kısmı (\'kasnak\') kalın halatla desteklenir, paça kısmı (\'paçabent\') keçe ve iple dize sıkıca bağlanır.'),
  ('Yün çorapların ve eldivenlerin dikişsiz, boru (silindir) biçiminde örülebilmesi için Anadolu kadınlarının yüzyıllardır kullandıkları geleneksel şiş düzeni hangisidir?', 'İki ucu sivri beş adet ince şiş', ['Bir ucu topuzlu tek bir kalın ahşap örgü şişi', 'Dişli demir kirkit ve ahşap mekik ikilisi', 'Ucu çengelli tek bir dantel tığı'], 'Geleneksel Türk el örgüsü çoraplar iki ucu açık 5 metal/ahşap şişle burundan veya konçtan başlanarak dairesel örülür; böylece ayağı vuran yan dikiş oluşmaz.'),
  ('Geleneksel el dokuması halı ve kilimlerin uçlarındaki çözgü ipliklerinin dokuma bittikten sonra sökülmemesi için gruplar hâlinde düğümlenip örülmesiyle oluşturulan kenar bitişine ne ad verilir?', 'Saçak bağlama', ['Kordon içine tel kıvırma', 'Sıcak ziftle mühürleme', 'Şaplı suda kasarlama'], 'Kilim ve halı tezgâhtan kesildiğinde atkıların kayıp dökülmemesi için boşta kalan çözgü uçları balıksırtı, makrome veya burma düğümlerle saçak hâlinde kilitlenir.'),
  ('Bolu\'nun Göynük ve Mudurnu ilçeleri ile Kastamonu\'da el tezgâhlarında dokunan, sofra bezi ve başörtüsü olarak kullanılan sarı-kırmızı-mavi kenar nakışlı pamuklu dokuma geleneğinde sofra altlığının işlevi nedir?', 'Yer sinisinin altına serilerek dökülen ekmek kırıntılarının bereket saygısıyla toplanmasını sağlamak', ['Sıcak bakır tencerenin ocak ateşi üzerinde tutuşturulmasına yaramak', 'Yağmurlu günlerde çatı kiremitlerinin üzerini örtmek', 'At ve öküzlerin koşum takımlarına yular ipi olmak'], 'Anadolu\'da \'sofra bezi\' (yaygı), kasnak ve sini altına genişçe serilen, nimete saygının gereği olarak tek bir ekmek kırıntısının bile yere basılmamasını sağlayan dokumadır.'),
  ('Geleneksel Türk el sanatlarında dikiş iğnesi ve ipek ya da naylon iplik kullanılarak düğümleme tekniğiyle oluşturulan üç boyutlu dantel türüne ne ad verilir?', 'İğne oyası', ['Tığ işi firkete örgüsü', 'Kasnak üstü hesap işi', 'Mekik sarma kanaviçe'], 'İğne oyası, iğne ve iplikle zürafa adı verilen temel düğümler üzerine inşa edilen üç boyutlu geleneksel Türk dantel sanatıdır.'),
  ('Geleneksel tel kırma sanatının en karakteristik merkezi olarak bilinen ve coğrafi işaretle tescillenen ilimiz hangisidir?', 'Bartın', ['Amasya', 'Burdur', 'Sinop'], 'Bartın tel kırma sanatı, yassı gümüş veya bakır tellerin makas kullanılmadan elle kırılarak tül üzerine işlenmesiyle ün kazanmıştır.'),
  ('Giresun\'un Çanakçı ilçesine bağlı Kuşköy\'de engebeli arazi şartlarında uzaktan haberleşmek amacıyla geliştirilen kültürel miras unsuru hangisidir?', 'Islık dili', ['Duman işareti', 'Güvercin postası', 'Davul telgrafı'], 'Kuşköy\'de vadiler arasında hecelerin ıslık tonlarına dönüştürülmesiyle kurulan ıslık dili (kuş dili), UNESCO Acil Koruma Gerektiren Somut Olmayan Kültürel Miras Listesi\'ndedir.'),
  ('Kırsal yerleşimlerde köy halkının tarla hasadı, ev yapımı veya yol onarımı gibi işleri el birliğiyle ve karşılıksız yardımlaşarak gerçekleştirmesine ne ad verilir?', 'İmece', ['Gedik', 'Narh', 'Lonca'], 'İmece, Anadolu köy kültüründe ortak veya bireysel büyük işlerin dayanışma ruhuyla topluca yapılması geleneğidir.'),
  ('Geleneksel sim sırma işlemeciliğinde özellikle bindallı, cepken ve bohça gibi ürünleriyle öne çıkan ve coğrafi işaret alan şehrimiz hangisidir?', 'Kahramanmaraş', ['Kırklareli', 'Zonguldak', 'Gümüşhane'], 'Kahramanmaraş sim sırma sanatı, kadife veya atlas kumaş üzerine karton kalıplar yerleştirilerek sim ve sırma ipliklerle yapılan köklü bir işleme geleneğidir.'),
  ('Çankırı başta olmak üzere İç Anadolu\'da kış gecelerinde bir araya gelinerek müzik, sohbet, oyun ve ahlaki eğitim etrafında sürdürülen geleneksel erkek meclisi hangisidir?', 'Yaren sohbeti', ['Sıra gecesi', 'Gezek meclisi', 'Barana toplantısı'], 'Yaren teşkilatı ve sohbetleri, Ahilik ilkelerine dayanan kuralları, başağası, musahipleri ve orta oyunlarıyla özellikle Çankırı yöresinin simgesidir.'),
  ('İki ucu sivri, ortası iplik sarmaya elverişli oval ve yassı küçük el aracıyla düğümler atılarak yapılan oya çeşidi hangisidir?', 'Mekik oyası', ['Tığ oyası', 'Koza oyası', 'Boncuk oyası'], 'Mekik oyası, özel mekik aletine sarılı ipliğin parmak hareketleriyle ilmeklenip sıkıştırılmasıyla oluşturulan zarif bir el sanatıdır.'),
  ('İğne oyasında yazma veya tülbent kenarına ilk sıra olarak çekilen ve üstteki tüm motiflerin zeminini oluşturan temel düğüm sırasına ne ad verilir?', 'Zürafa', ['Pırpır', 'Çitlenbik', 'Fıstık'], 'Zürafa, kumaş kenarını kıvırarak sabit aralıklarla atılan ilk düğüm sırasıdır ve iğne oyasının temel taşıdır.'),
  ('Tel kırma işleme tekniğini diğer geleneksel nakış türlerinden ayıran en belirgin uygulama kuralı nedir?', 'Makas kullanmadan telin elle bükülüp koparılması', ['İpliğin balmumu ile sertleştirilerek dikilmesi', 'Kumaşın altına kalın meşin tabaka yapıştırılması', 'Motiflerin yalnızca tığ yardımıyla zincirlenmesi'], 'Tel kırma sanatında yassı metal tel, özel iğneyle tül gözeneklerinden geçirildikten sonra makas değdirilmeden el hareketiyle kırılarak koparılır.'),
  ('İğne oyaları aracılığıyla Anadolu kadınının duygularını, sevincini, sitemini veya medeni durumunu sözsüz olarak ifade etmesi hangi kavramla açıklanır?', 'Sessiz iletişim dili', ['Ferman hattı geleneği', 'Lonca şifreleme düzeni', 'Minyatür istif sanatı'], 'Anadolu\'da oyaların renkleri ve motifleri (biber oyası, çayır çimen oyası vb.) kadının aile içi veya toplumsal mesajlarını aktardığı sessiz bir iletişim dilidir.'),
  ('Sim sırma işlemeciliğinde motiflerin kumaş yüzeyinde kabarık ve üç boyutlu durmasını sağlamak için sim sargısının altına genellikle hangi malzeme yerleştirilir?', 'Kesilmiş karton veya mukavva kalıp', ['İnce dövülmüş kurşun levha parçası', 'Kurutulmuş ıhlamur ağacı kabuğu', 'Bükülmüş ham keten halat demeti'], 'Sim sırma tekniğinde önce karton veya mukavvadan kesilen motifler kumaşa tutturulur, ardından sim iplik bu kalıbın üzerinden sarılarak kabartma elde edilir.'),
  ('Kuşköy\'de halk arasında "kuş dili" olarak da anılan ıslık dili, UNESCO\'nun hangi listesine kaydedilmiştir?', 'Acil Koruma Gerektiren Somut Olmayan Kültürel Miras Listesi', ['Dünya Doğal ve Karma Miras Alanları Envanter Listesi', 'Dünya Belleği Yazma ve Arşiv Belgeleri Kütüğü', 'Yaratıcı Şehirler Ağı Gastronomi ve Zanaat Listesi'], 'Nesilden nesile aktarımı teknoloji nedeniyle azaldığı için ıslık dili, UNESCO Acil Koruma Gerektiren Somut Olmayan Kültürel Miras Listesi\'ne alınmıştır.'),
  ('Geleneksel Yaren meclislerinde kapının açık olması ve bacanın tütmesi ilkeleri hangi toplumsal değeri simgeler?', 'Cömertlik, misafirperverlik ve paylaşımcılık', ['Resmi vergi kayıtlarının eksiksiz tutulması', 'Askeri nöbet düzeninin kesintisiz sürdürülmesi', 'Ticari sırların lonca dışına çıkarılmaması'], 'Yaren kültüründe üç şeyin (kapı, alın, sofra) açık olması misafirperverliği, dürüstlüğü ve cömertliği temsil eder.'),
  ('İpek böceği kozalarının kesilip şekillendirilmesi ve iğne ya da tığ oyasıyla birleştirilmesiyle yapılan geleneksel oya türü hangisidir?', 'Koza oyası', ['Filiz oyası', 'Mum oyası', 'Yün oyası'], 'Koza oyası, özellikle Bursa, Bilecik ve Muğla gibi ipekçilik merkezlerinde kozaların taç yaprağı biçiminde kesilip renklendirilmesiyle yapılır.'),
  ('İmece geleneğinde yardıma gelen komşulara iş sahibinin yemek veya ikram hazırlaması nasıl bir işlev görür?', 'Sosyal dayanışmayı ve birliktelik duygusunu pekiştirir', ['Çalışan işçilerin günlük yevmiye borcunu resmen kapatır', 'Köy sandığına ödenecek zorunlu vergiyi ortadan kaldırır', 'Üretilen mahsulün mülkiyetini tüm köylüye eşit dağıtır'], 'İmecede maddi ücret ödenmez; birlikte yenen yemek, şükran duygusunu ve komşuluk bağlarını güçlendiren törensel bir paylaşımdır.'),
  ('Tel kırma işlemelerinde zemin kumaşı olarak geleneksel biçimde en çok hangi dokuma tercih edilir?', 'Gözenekli tül veya krep kumaş', ['Kalın çuval bezi veya kanaviçe', 'Sık dokunmuş keçe veya aba', 'Su geçirmez muşamba veya branda'], 'Tel kırma iğnesinin kumaşı delmeden gözeneklerden geçebilmesi ve telin parlaklığını göstermesi için kare veya petek gözenekli tüller kullanılır.'),
  ('Geleneksel bindallı elbiselerde koyu bordo, mor veya lacivert kadife üzerine sim ve sırma ile en sık işlenen bezeme grubu hangisidir?', 'Yaprak, dal, lale ve karanfil gibi bitkisel motifler', ['Savaş gemisi, kale burcu ve top arabası figürleri', 'Av sahnesi, yırtıcı hayvan ve mitolojik canavarlar', 'Çivi yazısı, hiyeroglif ve antik sikke kabartmaları'], 'Bindallı ("bin dallı") adını, kadife yüzeyini baştan başa saran kıvrık dallar, yapraklar ve çiçeklerden oluşan zengin bitkisel sırma bezemelerinden alır.'),
  ('Balıkesir yöresinde Yaren geleneğinin bir benzeri olarak müzik, sohbet ve geleneksel oyunlarla yaşatılan kültürel meclis aşağıdakilerden hangisidir?', 'Barana', ['Gezek', 'Kürsübaşı', 'Oturmah'], 'Balıkesir (özellikle Dursunbey ve Sındırgı) yöresinde erkeklerin belirli kurallar çerçevesinde toplanıp türküler söylediği geleneksel sohbete Barana denir.'),
  ('İğne oyası yapımında motifin kenarlarında bırakılan küçük, tekli veya çoklu ilmek çıkıntılarına ustalar arasında ne ad verilir?', 'Pırpır', ['Şiraze', 'Teyel', 'Kolan'], 'Zürafa veya köprü üzerine ipliğin biraz bol bırakılıp düğümlenmesiyle oluşturulan damla biçimli küçük kulakçıklara pırpır ya da kirpik denir.'),
  ('Mekik oyasında iki mekik veya mekik ile yumak ipliğinin birlikte kullanılması sanatçıya hangi teknik avantajı sağlar?', 'İki renkli ve daha geniş halkalı motifler örebilmeyi', ['Kumaşı kasnağa germeden doğrudan tel kırabilmeyi', 'Metal pulları eriterek tül üzerine yapıştırabilmeyi', 'İpliği hiç düğüm atmadan keçe yüzeyine kaynaştırmayı'], 'Tek mekikle yalnızca halka yapılırken, yumak ipliği veya ikinci mekik eklendiğinde zincir (köprü) bölümleri ve çift renkli kompozisyonlar oluşturulabilir.'),
  ('Anadolu\'da gelinlik kızların evlilik öncesi el emeği göz nuru oyalarını, tel kırmalarını ve sırma işlemelerini biriktirip sergilediği geleneksel bütüne ne ad verilir?', 'Çeyiz', ['Tereke', 'Vakfiye', 'İcazetname'], 'Çeyiz, genç kızların yıllar boyunca hazırladığı oyalı yazmalar, işlemeli bohçalar ve dokumalardan oluşan somut ve somut olmayan kültürel miras birikimidir.'),
  ('Bir köyde düğün yemeği için buğday dövülmesi (keşkeklik hazırlanması) veya kışlık erişte kesiminin komşu kadınlarca sırayla yapılması hangi kavramın doğrudan örneğidir?', 'İmece usulü yardımlaşma', ['Lonca gedik tahsisi', 'Müzayede usulü satış', 'İltizam usulü vergilendirme'], 'Kışlık erzak hazırlığı veya düğün-cenaze işlerinin mahalle ve köy sakinlerince sırayla el birliğiyle yapılması imece kültürünün günlük yaşamdaki yansımasıdır.'),
  ('Osmanlı şehirlerinde mücevher, kıymetli kumaş, silah ve değerli belgelerin alınıp satıldığı ve korunduğu kalın taş duvarlı, kubbeli kapalı çarşı yapısına ne ad verilir?', 'Bedesten', ['İmarethane', 'Muvakkithane', 'Darüşşifa'], 'Bedesten (bezzazistan), kıymetli ticari malların güvenli biçimde saklandığı ve satıldığı sağlam taş/tuğla örgülü ticaret merkezidir.'),
  ('Tarihi Türk çarşılarında aynı iş kolunda faaliyet gösteren esnaf dükkânlarının bir sokak boyunca karşılıklı iki sıra halinde dizilmesiyle oluşan çarşı düzenine ne ad verilir?', 'Arasta', ['Şifahane', 'Medrese', 'Sebil'], 'Arasta, genellikle bir külliyeye gelir sağlamak amacıyla aynı loncaya mensup esnafın sıralı dükkânlarından oluşan üstü açık veya örtülü çarşıdır.'),
  ('Eski, baskısı tükenmiş, nadir veya ikinci el kitapların, dergilerin ve el yazmalarının alınıp satıldığı geleneksel meslek erbabına ne ad verilir?', 'Sahaf', ['Hattat', 'Müzehhip', 'Nakkaş'], 'Sahaflar, yalnızca kitap ticareti yapmakla kalmayıp kültürel hafızayı ve nadir eserleri okuyucu ve araştırmacılarla buluşturan kitap uzmanlarıdır.'),
  ('Dağınık haldeki kitap formalarını dikip birleştiren ve dışına deri, bez veya ebru kaplı mukavva kapak takarak ciltleyen geleneksel zanaatkâra ne ad verilir?', 'Mücellit', ['Mücellid olmayan müstensih', 'Hakkâk', 'Varrak'], 'Cilt (deri/kapak) kelimesinden türeyen mücellit, el yazması veya matbu eserleri koruyucu ve estetik kapaklarla ciltleyen ustadır.'),
  ('Yatak, yorgan ve yastıkların içinde zamanla keçeleşip sertleşen pamuk veya yünleri yay ve tokmak yardımıyla atarak kabartan ustaya ne ad verilir?', 'Hallaç', ['Saraç', 'Semerci', 'Kalaycı'], 'Hallaç, kirişli büyük yayına tokmakla vurarak çıkardığı titreşimlerle pamuk ve yün liflerini havalandırıp yumuşatan geleneksel zanaatkârdır.'),
  ('Koşum takımları, eyer, dizgin, kemer, çanta ve kılıf gibi işlenmiş deriden (kösele ve meşinden) eşyalar üreten ve onaran zanaatkâra ne ad verilir?', 'Saraç', ['Debbağ', 'Kavaf', 'Keçeci'], 'Saraçlık, tabaklanmış deriyi kesip dikerek ve süsleyerek başta at koşum ve eyer takımları olmak üzere dayanıklı deri ürünler yapma sanatıdır.'),
  ('At, eşek ve katır gibi binek ve yük hayvanlarının sırtına vurulan, yükün hayvana zarar vermeden taşınmasını sağlayan özel donanımı üreten ustaya ne ad verilir?', 'Semerci', ['Nalbant', 'Çerçi', 'Urgancı'], 'Semerci, ağaç iskelet, kamış/saz otu, keçe ve deri kullanarak hayvanın sırt anatomisine uygun semer (palan) imal eden ustadır.'),
  ('Bakır kap kacakların gıdaları zehirlemesini önlemek amacıyla yüzeylerini temizleyip erimiş kalay madeniyle kaplayan geleneksel meslek erbabı hangisidir?', 'Kalaycı', ['Kazancı', 'Demirci', 'Lehimci'], 'Bakır kaplar zamanla oksitlenip yeşilimsi bakır çürüğü (zehirli bileşikler) oluşturduğundan, kalaycılar tarafından düzenli olarak kalaylanır.'),
  ('Geleneksel bakır mutfak eşyalarının iç yüzeyinin belirli aralıklarla kalaylatılmasının en temel sağlık gerekçesi nedir?', 'Bakırın asitli gıdalarla tepkimeye girerek oluşturduğu zehirli bileşiklerin yemeğe karışmasını önlemek', ['Bakır tencerenin ağırlığını yarı yarıya azaltarak taşınmasını kolaylaştırmak', 'Yemeklerin hiç ateş yakılmadan oda sıcaklığında kendiliğinden pişmesini sağlamak', 'Bakır kabın mıknatıs özelliği kazanarak demir kaşıkları tutmasını sağlamak'], 'Kalay tabakası, bakır yüzey ile yiyecekler arasında koruyucu ve gıdaya uygun bir bariyer oluşturarak bakır zehirlenmesini engeller.'),
  ('Hallaçların pamuk veya yünü kabartırken yay kirişine vurmak için kullandıkları, iki ucu boğumlu özel ahşap araca ne ad verilir?', 'Çekmek', ['Mekik', 'Cendere', 'Biz'], 'Hallaç ustası sol eliyle yayı tutarken sağ elindeki "çekmek" veya "tokmak" adı verilen ahşap aletle kiriş teline vurarak pamuğu atar.'),
  ('İstanbul\'da Beyazıt Camii ile Kapalıçarşı arasında yer alan ve Osmanlı\'dan beri kitapçıların merkezi olan tarihi çarşının adı nedir?', 'Sahaflar Çarşısı', ['Mısır Çarşısı', 'Sipahi Çarşısı', 'Bakırcılar Çarşısı'], 'Beyazıt\'taki tarihi Sahaflar Çarşısı (eski Hakkâklar Çarşısı alanı), yüzyıllardır ilim ve kültür dünyasının en önemli kitap merkezidir.'),
  ('"Atılan pamuk gibi olmak" veya "hallaç pamuğu gibi atmak" deyimleri, hallaçlık mesleğinin hangi işleminden esinlenerek Türkçeye yerleşmiştir?', 'Sıkışmış pamuk yığınlarının yay darbesiyle havaya savrulup darmadağın ve kabarık hale getirilmesinden', ['Pamuk tarlalarının sonbahar yağmurlarıyla çamur altında kalmasından', 'Pamuk ipliklerinin boya kazanlarında kaynatılarak renklendirilmesinden', 'Pamuk balyalarının deve kervanlarıyla bedestene taşınmasından'], 'Yay kirişinin pamuk kütlesine hızla çarpmasıyla liflerin havada uçuşup dağılması, dilimizde "hallaç pamuğu gibi atmak" deyimine kaynaklık etmiştir.'),
  ('Saraçların kalın kösele ve derileri dikmeden önce iğnenin geçebileceği delikleri açmak için kullandıkları sivri uçlu metal el aletine ne ad verilir?', 'Biz', ['Tığ', 'Keser', 'Perdah'], 'Kalın deri ve kösele normal dikiş iğnesiyle delinemeyeceği için saraçlar ahşap saplı, çelik sivri uçlu "biz" ile önce delik açar, ardından mumlu iplikle diker.'),
  ('Tarihi külliyelerin bünyesinde inşa edilen arasta ve bedestenlerin kira gelirleri Osmanlı şehir sisteminde öncelikle nereye aktarılırdı?', 'Cami, medrese, aşevi ve şifahane gibi vakıf kurumlarının giderlerine', ['Yabancı tüccarların gümrük vergisi muafiyeti fonlarına', 'Yalnızca saray muhafızlarının merasim kıyafeti harcamalarına', 'Şehir dışındaki av köşklerinin bahçe düzenlemesi bütçesine'], 'Vakıf sisteminde arasta ve bedesten gibi gelir getirici (akar) ticari yapılar, külliyenin eğitim, sağlık ve sosyal yardım hizmetlerini finanse ederdi.'),
  ('Kalaycıların bakır kabın üzerine kalayı parlak ve pürüzsüz biçimde yaymak ve kalayın yüzeye tutunmasını sağlamak için serptikleri beyaz toz madde nedir?', 'Nişadır', ['Tebeşir tozu', 'Kireç kaymağı', 'Kaya tuzu'], 'Isıtılan bakır yüzeye serpilen nişadır, oksit tabakasını çözerek (flaks görevi görerek) erimiş kalayın bakıra tam yapışmasını ve ayna gibi parlamasını sağlar.'),
  ('Semer yapımında hayvanın terini emmesi ve sırtının yara (cidago vurması) olmaması için semerin iç kısmını doldurmakta kullanılan en yaygın doğal bitki hangisidir?', 'Göl ve bataklık kamışı / saz otu', ['Kurutulmuş çam kozalağı ve meşe palamudu', 'Öğütülmüş ceviz kabuğu ve zeytin çekirdeği', 'İnce kıyılmış dikenli çalı ve ısırgan sapı'], 'Esnek, hafif ve ter emici yapısıyla kurutulmuş saz/kındıra kamışı, keçe ile kaplanan semer yastıklarının içine doldurularak hayvanın sırtını korur.'),
  ('Bir mücellidin kitabın sırt kısmının dağılmasını önlemek ve sayfaları bir arada tutmak için sırtın üst ve alt uçlarına renkli ipek ipliklerle ördüğü koruyucu şeride ne ad verilir?', 'Şiraze', ['Miklep', 'Şemse', 'Köşebent'], 'Şiraze, kitap formalarının sırt uçlarını sağlamlaştıran estetik örgüdür; mecaz anlamda "şirazeden çıkmak" deyimi de düzenin bozulmasını anlatır.'),
  ('İstanbul Kapalıçarşı\'nın çekirdeğini oluşturan ve Fatih Sultan Mehmed döneminde inşa ettirilen iki tarihi bedestenin adları nelerdir?', 'Cevahir (İç) Bedesteni ve Sandal Bedesteni', ['Mısır Bedesteni ve Galata Bedesteni', 'Üsküdar Bedesteni ve Eyüp Bedesteni', 'Tophane Bedesteni ve Beşiktaş Bedesteni'], 'Kapalıçarşı, Fatih döneminde yaptırılan Cevahir Bedesteni (kıymetli eşyalar) ve Sandal Bedesteni (ipekli-pamuklu kumaşlar) etrafında gelişmiştir.'),
  ('Saraçhanebaşı gibi semt adlarının Anadolu ve Rumeli şehirlerinde sıkça görülmesi tarihsel olarak neyin göstergesidir?', 'Aynı meslek grubundaki zanaatkârların şehirde belirli bir çarşı veya mahallede toplu halde çalıştığının', ['Şehirdeki tüm evlerin yalnızca deri çadırlardan inşa edildiğinin', 'Saraçların şehir merkezine girmesinin yasaklandığının', 'O bölgede yalnızca tarım ve balıkçılık yapıldığının'], 'Geleneksel Osmanlı şehir planlamasında denetim, hammadde temini ve lonca dayanışması amacıyla saraçlar, bakırcılar, sahaflar kendi adlarını taşıyan çarşılarda toplanırdı.'),
  ('Kalaycı dükkânlarında ocağın ateşini harlamak ve bakır tavayı gereken sıcaklığa ulaştırmak için kullanılan geleneksel hava üfleme aracı nedir?', 'Körük', ['Çıkrık', 'Cendere', 'Tefe'], 'Kalaycı ocağındaki odun kömürü ateşini canlandırmak için deri ve ahşaptan yapılmış el veya ayak körüğü kullanılır.'),
  ('Bir sahafın elindeki eserin "ilk baskı", "müellif imzalı" veya "nadir nüsha" olması o kitabın değerini nasıl etkiler?', 'Eserin belge, koleksiyon ve kültür tarihi değerini büyük ölçüde artırır', ['Sayfa kağıtları eskidiği için kitabın okunamaz sayılarak hurdaya ayrılmasına yol açar', 'Kitabın fiyatının yeni basılmış cep kitaplarından daha düşük olmasına neden olur', 'Eserin yalnızca mücellitler tarafından parçalanıp mukavva yapımında kullanılmasını gerektirir'], 'Sahafiye kültüründe bir kitabın baskı adedinin azlığı, tarihsel tanıklığı ve yazarının (müellifinin) imzasını taşıması onu eşsiz bir kültür varlığı yapar.'),
];
